create table if not exists public.sales_channel_category_mappings(id uuid primary key default gen_random_uuid(),channel_key text not null,connection_key text not null default 'default',source_category text not null,source_subtype text not null default '',external_category_id text not null,external_category_name text,attribute_schema jsonb not null default '{}'::jsonb,status text not null default 'DRAFT' check(status in('DRAFT','VERIFIED','BLOCKED')),verified_at timestamptz,last_error text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(channel_key,connection_key,source_category,source_subtype));
create table if not exists public.sales_channel_product_mappings(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,channel_key text not null,connection_key text not null default 'default',external_category_id text,external_sku text,external_product_id text,external_variant_id text,attributes jsonb not null default '{}'::jsonb,status text not null default 'DRAFT' check(status in('DRAFT','READY','BLOCKED')),blockers jsonb not null default '[]'::jsonb,validated_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(product_id,channel_key,connection_key));
alter table public.sales_channel_category_mappings enable row level security;alter table public.sales_channel_product_mappings enable row level security;
create policy channel_category_service on public.sales_channel_category_mappings for all to service_role using(true) with check(true);create policy channel_product_service on public.sales_channel_product_mappings for all to service_role using(true) with check(true);
create or replace view public.sales_channel_readiness_v as select r.channel_key,r.label,r.adapter_mode,r.enabled,r.auto_publish,c.connection_key,c.status connection_status,c.activation_status,c.environment,c.verified_at,case when r.channel_key in('lazada','tiktok_shop') then case when c.status='CONNECTED' and c.activation_status in('VERIFIED','ACTIVE') and c.verified_at is not null then 'MAPPING_REQUIRED' else 'AUTH_REQUIRED' end else coalesce(c.activation_status,'LOCKED') end readiness,(select count(*) from public.sales_channel_category_mappings m where m.channel_key=r.channel_key and m.connection_key=coalesce(c.connection_key,'default') and m.status='VERIFIED') verified_category_mappings,(select count(*) from public.sales_channel_product_mappings m where m.channel_key=r.channel_key and m.connection_key=coalesce(c.connection_key,'default') and m.status='READY') ready_product_mappings from public.sales_channel_registry r left join public.sales_channel_connections c on c.channel_key=r.channel_key;
create or replace function public.sales_channel_can_activate(p_channel_key text,p_connection_key text default 'default') returns table(ok boolean,blockers text[]) language sql security definer set search_path=public as $$ with x as(select r.channel_key,c.status,c.activation_status,c.verified_at,(select count(*) from sales_channel_category_mappings m where m.channel_key=r.channel_key and m.connection_key=p_connection_key and m.status='VERIFIED') cats,(select count(*) from sales_channel_product_mappings m where m.channel_key=r.channel_key and m.connection_key=p_connection_key and m.status='READY') prods from sales_channel_registry r left join sales_channel_connections c on c.channel_key=r.channel_key and c.connection_key=p_connection_key where r.channel_key=p_channel_key) select (coalesce(status,'')='CONNECTED' and activation_status in('VERIFIED','ACTIVE') and verified_at is not null and (p_channel_key not in('lazada','tiktok_shop') or(cats>0 and prods>0))) ok,array_remove(array[case when coalesce(status,'')<>'CONNECTED' then 'AUTH_REQUIRED' end,case when verified_at is null then 'CONNECTION_NOT_VERIFIED' end,case when p_channel_key in('lazada','tiktok_shop') and cats=0 then 'CATEGORY_MAPPING_REQUIRED' end,case when p_channel_key in('lazada','tiktok_shop') and prods=0 then 'PRODUCT_MAPPING_REQUIRED' end],null) blockers from x $$;
revoke all on function public.sales_channel_can_activate(text,text) from public,anon,authenticated;grant execute on function public.sales_channel_can_activate(text,text) to service_role;update public.sales_channel_registry set auto_publish=false where channel_key in('lazada','tiktok_shop','facebook_page','facebook_marketplace','shopee');